## Setup ----
testthat::skip_if(
  Sys.getenv("RUN_SLOW_TESTS") != "true",
  "Skipping: RUN_SLOW_TESTS is not set to true."
)

# TMB records the objective once, at the starting values, and replays that
# tape during optimization and in sdreport(). C++ code that branches on the
# value of an estimated parameter, such as an `if` on a `Type`, keeps the
# branch taken at the starting values, with no error or warning. Each case
# below compares that tape with new tapes made at 2 points on either side of
# the starting values. They differ if a branch on the tape depends on an
# estimated value. Tapes with the same branches run the same operations, so
# they agree to rounding error.
#
# Each case estimates the parameters of the module it is about and checks
# that they have a nonzero gradient, so they are on the tape. A branch on a
# constant is fine, because a constant is data on the tape.
#
# The default model has logistic selectivity, EWAA growth, Beverton--Holt
# recruitment with log_devs as random effects, lognormal catch and index,
# and multinomial compositions. Each case changes only the parts of it that
# the case checks.
data("data_big")
data_4_model <- FIMSFrame(data_big)
default_parameters <- setup_default_parameters(data = data_4_model)
ages <- get_ages(data_4_model)
n_ages <- length(ages)

#' Compare a tape made at the starting values with new tapes made at 2
#' perturbed points
#'
#' @param parameters A tibble returned from [setup_default_parameters()].
#' @param data A `FIMSFrame` object.
#' @return A list with:
#'   * `all_finite`: whether the objective and gradient from every tape at
#'     both points are finite.
#'   * `largest_difference`: the largest difference between the objective and
#'     gradient values of the tape made at the starting values and of the new
#'     tapes, relative to each value or to 1 for a value near 0.
#'   * `nonzero_gradient`: the parameters, as `module.label`, with at least 1
#'     value whose gradient at the first point is not 0.
compare_tapes <- function(parameters, data) {
  input <- initialize_fims(parameters = parameters, data = data)
  # Without random = "re", fn() and gr() replay the tape of the joint
  # likelihood of the fixed and random effects. So the tapes are compared
  # directly, with no inner optimization, and the random effects get a
  # gradient too.
  start_tape <- TMB::MakeADFun(
    data = list(),
    parameters = input[["parameters"]],
    DLL = "FIMS",
    silent = TRUE
  )
  # A branch is found only if a point crosses its threshold. Every value
  # moves by 0.1 on the scale it is estimated on, which is about 10% for a
  # log-scale value. The direction of each value is random at the first point
  # and reversed at the second point. So a threshold at a starting value is
  # crossed at 1 of the 2 points.
  signs <- withr::with_seed(1, purrr::map(
    input[["parameters"]],
    \(x) sample(c(-1, 1), length(x), replace = TRUE)
  ))
  points <- purrr::map(c(1, -1), \(direction) {
    purrr::map2(input[["parameters"]], signs, \(x, sign) {
      x + direction * 0.1 * sign
    })
  })
  objective_and_gradient <- function(tape, point) {
    point <- unlist(point, use.names = FALSE)
    c(tape[["fn"]](point), tape[["gr"]](point))
  }
  taped_at_start <- points |>
    purrr::map(\(point) objective_and_gradient(start_tape, point)) |>
    unlist()

  # The perturbed values go to TMB, not to the tibble, because the tibble
  # gives some values on another scale, such as growth lengths on the natural
  # scale, which are estimated on the log scale. A new model, rather than
  # obj$retape(), does not reuse anything the C++ objects stored while the
  # first tape was made.
  taped_at_points <- purrr::map(points, \(point) {
    initialize_fims(parameters = parameters, data = data)
    new_tape <- TMB::MakeADFun(
      data = list(),
      parameters = point,
      DLL = "FIMS",
      silent = TRUE
    )
    objective_and_gradient(new_tape, point)
  })
  # Names are module.id.label.id, such as Selectivity.1.slope.2.
  parameter_names <- c(
    names(get_parameter_names(as.list(input[["parameters"]][["p"]]))),
    names(get_random_names(as.list(input[["parameters"]][["re"]])))
  )
  clear()
  taped_at_point <- unlist(taped_at_points)
  list(
    all_finite = all(is.finite(c(taped_at_start, taped_at_point))),
    largest_difference = max(
      abs(taped_at_start - taped_at_point) / pmax(abs(taped_at_point), 1)
    ),
    nonzero_gradient = unique(sub(
      "^([^.]+)\\.[0-9]+\\.(.+)\\.[0-9]+$", "\\1.\\2",
      parameter_names[taped_at_points[[1]][-1] != 0]
    ))
  )
}

## IO correctness ----
test_that("the tape for each selectivity type matches new tapes on both sides of the starting values", {
  # Every fleet uses the type, so it is checked for a fishery and a survey.
  # The Logistic case is the default model.
  selectivity_types <- eval(formals(setup_default_Selectivity)[["module_type"]])
  for (selectivity_type in selectivity_types) {
    selectivity <- get_fleets(data_4_model) |>
      purrr::map(\(fleet) {
        setup_default_Selectivity(data_4_model, fleet, selectivity_type)
      }) |>
      dplyr::bind_rows()
    tapes <- default_parameters |>
      dplyr::filter(module_name != "Selectivity") |>
      dplyr::bind_rows(selectivity) |>
      compare_tapes(data = data_4_model)
    estimated <- selectivity |>
      dplyr::filter(estimation_type != "constant") |>
      dplyr::pull(label) |>
      unique()

    #' @description Test that each estimated selectivity parameter has a nonzero gradient.
    expect_equal(
      object = setdiff(
        paste("Selectivity", estimated, sep = "."),
        tapes[["nonzero_gradient"]]
      ),
      expected = character(0),
      label = selectivity_type
    )
    #' @description Test that, with each selectivity type, every tape gives a finite objective and gradient at the 2 perturbed points.
    expect_true(tapes[["all_finite"]], label = selectivity_type)
    #' @description Test that, with each selectivity type, the tape made at the starting values gives the same objective and gradient at 2 perturbed points as new tapes made there.
    expect_lt(
      object = tapes[["largest_difference"]],
      expected = 1e-10,
      label = selectivity_type
    )
  }
})

test_that("the tape for each maturity type matches new tapes on both sides of the starting values", {
  # Maturity is constant by default, so it is estimated here.
  maturity_types <- eval(formals(setup_default_Maturity)[["module_type"]])
  for (maturity_type in maturity_types) {
    maturity <- setup_default_Maturity(data_4_model, maturity_type) |>
      dplyr::mutate(estimation_type = "fixed_effects")
    tapes <- default_parameters |>
      dplyr::filter(module_name != "Maturity") |>
      dplyr::bind_rows(maturity) |>
      compare_tapes(data = data_4_model)

    #' @description Test that each maturity parameter has a nonzero gradient.
    expect_equal(
      object = setdiff(
        paste("Maturity", maturity[["label"]], sep = "."),
        tapes[["nonzero_gradient"]]
      ),
      expected = character(0),
      label = maturity_type
    )
    #' @description Test that, with each maturity type, every tape gives a finite objective and gradient at the 2 perturbed points.
    expect_true(tapes[["all_finite"]], label = maturity_type)
    #' @description Test that, with each maturity type, the tape made at the starting values gives the same objective and gradient at 2 perturbed points as new tapes made there.
    expect_lt(
      object = tapes[["largest_difference"]],
      expected = 1e-10,
      label = maturity_type
    )
  }
})

test_that("the tape for each recruitment type and process matches new tapes on both sides of the starting values", {
  # The stock--recruit parameters are the rows without a distribution type.
  # Steepness is constant by default, so all of them are estimated here.
  # log_devs are deviations from the stock--recruit curve and start at 0.
  # log_r is log recruitment, which starts at log R0.
  log_rzero <- default_parameters |>
    dplyr::filter(label == "log_rzero") |>
    dplyr::pull(value)
  recruitment_types <- eval(formals(setup_default_Recruitment)[["module_type"]])
  for (recruitment_type in recruitment_types) {
    recruitment <- setup_default_Recruitment(data_4_model, recruitment_type) |>
      dplyr::mutate(
        estimation_type = dplyr::if_else(
          is.na(distribution_type), "fixed_effects", estimation_type
        )
      )
    stock_recruit_labels <- recruitment |>
      dplyr::filter(is.na(distribution_type)) |>
      dplyr::pull(label)
    for (process in c("log_devs", "log_r")) {
      case <- paste(recruitment_type, process)
      tapes <- default_parameters |>
        dplyr::filter(module_name != "Recruitment") |>
        dplyr::bind_rows(recruitment) |>
        dplyr::mutate(
          value = dplyr::if_else(
            label == "log_devs" & process == "log_r", log_rzero, value
          ),
          label = dplyr::if_else(label == "log_devs", process, label)
        ) |>
        compare_tapes(data = data_4_model)

      #' @description Test that the stock--recruit parameters, the log_devs or log_r values, and their log_sd have a nonzero gradient.
      expect_equal(
        object = setdiff(
          c(
            paste("Recruitment", c(stock_recruit_labels, process), sep = "."),
            "dnorm.log_sd"
          ),
          tapes[["nonzero_gradient"]]
        ),
        expected = character(0),
        label = case
      )
      #' @description Test that, with each recruitment type and process, every tape gives a finite objective and gradient at the 2 perturbed points.
      expect_true(tapes[["all_finite"]], label = case)
      #' @description Test that, with each recruitment type and process, the tape made at the starting values gives the same objective and gradient at 2 perturbed points as new tapes made there.
      expect_lt(
        object = tapes[["largest_difference"]],
        expected = 1e-10,
        label = case
      )
    }
  }
})

test_that("the tape for each growth type matches new tapes on both sides of the starting values", {
  # EWAA, the default, has no parameters, and every other case uses it. Every
  # von Bertalanffy--Schnute parameter is estimated except the reference ages.
  # Length at age changes form at the young reference age with an `if` on its
  # value, so that age must be constant. The fleets' age-to-length keys come
  # from growth, so they are checked too. The delta-method case replaces the
  # sd interpolated between the 2 reference ages with the sd and correlations
  # of the log growth parameters.
  von_bertalanffy <- default_parameters |>
    dplyr::filter(module_name != "Growth") |>
    dplyr::bind_rows(
      setup_default_Growth(data_4_model, module_type = "VonBertalanffySchnute")
    ) |>
    dplyr::mutate(
      estimation_type = dplyr::if_else(
        module_name == "Growth" & !startsWith(label, "reference_age"),
        "fixed_effects", estimation_type
      )
    )
  delta_method_rows <- tibble::tibble(
    module_name = "Growth",
    module_type = "VonBertalanffySchnute",
    label = c(
      "log_sd_mean_length_young",
      "log_sd_mean_length_old",
      "log_sd_growth_coefficient",
      "mean_length_young_mean_length_old_logit_corr",
      "mean_length_young_growth_coefficient_logit_corr",
      "mean_length_old_growth_coefficient_logit_corr"
    ),
    value = c(rep(log(0.1), 3), rep(0, 3)),
    estimation_type = "fixed_effects"
  )
  growth_cases <- list(
    interpolated_sd = von_bertalanffy,
    delta_method_sd = von_bertalanffy |>
      dplyr::filter(!startsWith(label, "length_at_age_sd")) |>
      dplyr::bind_rows(delta_method_rows)
  )
  # The default population length bins are 1 mm wide, over 1,000 bins for
  # data_big, so 1 tape takes over a minute. Bins 50 mm wide, the width of
  # the fleet bins, take a few seconds and use the same code.
  data_50_mm_bins <- data_big |>
    dplyr::bind_rows(population_length_bin_rows(seq(0, 1150, by = 50))) |>
    FIMSFrame()
  for (case in names(growth_cases)) {
    parameters <- growth_cases[[case]]
    tapes <- compare_tapes(parameters, data = data_50_mm_bins)
    estimated <- parameters |>
      dplyr::filter(module_name == "Growth", estimation_type != "constant") |>
      dplyr::pull(label)

    #' @description Test that each estimated growth parameter has a nonzero gradient.
    expect_equal(
      object = setdiff(
        paste("Growth", estimated, sep = "."),
        tapes[["nonzero_gradient"]]
      ),
      expected = character(0),
      label = case
    )
    #' @description Test that, with each von Bertalanffy--Schnute sd, every tape gives a finite objective and gradient at the 2 perturbed points.
    expect_true(tapes[["all_finite"]], label = case)
    #' @description Test that, with each von Bertalanffy--Schnute sd, the tape made at the starting values gives the same objective and gradient at 2 perturbed points as new tapes made there.
    expect_lt(
      object = tapes[["largest_difference"]],
      expected = 1e-10,
      label = case
    )
  }
  growth_types <- default_parameters |>
    dplyr::bind_rows(von_bertalanffy) |>
    dplyr::filter(module_name == "Growth") |>
    dplyr::pull(module_type)
  #' @description Test that the default model and the growth cases use every growth type.
  expect_setequal(
    object = growth_types,
    expected = eval(formals(setup_default_Growth)[["module_type"]])
  )
})

test_that("the tape with ageing error matches new tapes on both sides of the starting values", {
  # Each age is read correctly with probability 0.7 and 1 year too old with
  # probability 0.3, and the plus group is always read correctly, as in
  # test-integration-ageing-error.R. Rows are true ages and columns are
  # observed ages. Ageing error has no parameters. It moves the expected age
  # compositions, which depend on the estimated selectivity.
  reads_older <- diag(0.7, n_ages)
  reads_older[cbind(1:(n_ages - 1), 2:n_ages)] <- 0.3
  reads_older[n_ages, n_ages] <- 1
  ageing_error_rows <- tibble::tibble(
    type = "ageing_error",
    fleet = NA_character_,
    age = rep(ages, times = n_ages),
    length = NA_real_,
    timing = NA_real_,
    observed = as.vector(t(reads_older)),
    unit = "proportion",
    uncertainty = as.character(rep(ages, each = n_ages))
  )
  tapes <- compare_tapes(
    default_parameters,
    data = FIMSFrame(dplyr::bind_rows(data_big, ageing_error_rows))
  )

  #' @description Test that the selectivity parameters, which pass through the expected age compositions, have a nonzero gradient.
  expect_equal(
    object = setdiff(
      c("Selectivity.inflection_point", "Selectivity.slope"),
      tapes[["nonzero_gradient"]]
    ),
    expected = character(0)
  )
  #' @description Test that, with ageing error, every tape gives a finite objective and gradient at the 2 perturbed points.
  expect_true(tapes[["all_finite"]])
  #' @description Test that, with ageing error, the tape made at the starting values gives the same objective and gradient at 2 perturbed points as new tapes made there.
  expect_lt(
    object = tapes[["largest_difference"]],
    expected = 1e-10
  )
})

test_that("the tape with normal likelihoods matches new tapes on both sides of the starting values", {
  # The lognormal and multinomial likelihoods of data_big are in every other
  # case. Here the catch and the survey1 age compositions are normal. The sd
  # of the catch is 10% of the observed catch. The compositions are numbers,
  # because a normal likelihood has no sample size to turn proportions into
  # numbers. The index stays lognormal, because log_q starts at 0, which puts
  # the expected index far above the data on the natural scale. The sd of
  # each likelihood is constant, so the case checks the estimated parameters
  # that pass through the expected values.
  data_normal <- data_big |>
    dplyr::mutate(
      is_catch = type == "catch",
      is_survey_comp = type == "age_comp" & fleet %in% "survey1",
      observed = dplyr::if_else(is_survey_comp, observed * 200, observed),
      unit = dplyr::if_else(is_survey_comp, "number", unit),
      uncertainty = dplyr::case_when(
        is_catch ~ paste0(
          "~ dnorm(mean = catch_expected, sd = ", 0.1 * observed, ")"
        ),
        is_survey_comp ~ "~ dnorm(mean = agecomp_expected, sd = 1)",
        .default = uncertainty
      )
    ) |>
    dplyr::select(-"is_catch", -"is_survey_comp") |>
    FIMSFrame()
  tapes <- compare_tapes(default_parameters, data = data_normal)

  #' @description Test that fishing mortality and selectivity, which pass through the normal expected values, have a nonzero gradient.
  expect_equal(
    object = setdiff(
      c("Fleet.log_Fmort", "Selectivity.inflection_point", "Selectivity.slope"),
      tapes[["nonzero_gradient"]]
    ),
    expected = character(0)
  )
  #' @description Test that, with normal likelihoods, every tape gives a finite objective and gradient at the 2 perturbed points.
  expect_true(tapes[["all_finite"]])
  #' @description Test that, with normal likelihoods, the tape made at the starting values gives the same objective and gradient at 2 perturbed points as new tapes made there.
  expect_lt(
    object = tapes[["largest_difference"]],
    expected = 1e-10
  )

  families <- list(data_4_model, data_normal) |>
    purrr::map(\(data) get_data(data)[["uncertainty"]]) |>
    unlist() |>
    unique() |>
    parse_data_distribution() |>
    purrr::pluck("family")
  #' @description Test that the default data and the normal case use every likelihood family in FIMS.
  expect_setequal(
    object = families[!is.na(families)],
    expected = FIMS::fims_distributions[["family"]]
  )
})

